const hoje = new Date();
const inicio = new Date();
inicio.setDate(hoje.getDate() - 30);
const fmt = d => d.toISOString().slice(0, 10).replace(/-/g, "");

return {
  json: {
    ...$json,
    dataInicial: fmt(inicio),
    dataFinal: fmt(hoje),
  }
};

const municipioId = $('Para cada município').item.json.id;
const response = $input.first().json;
const registros = response.data || response.registros || response.content || [];

// classifica por palavra-chave pra bater com scoring_weights.signal_type
// (que só tem 'edital_aberto' e 'obra_rodoviaria' associados a source='pncp')
const PALAVRAS_RODOVIA = ["rodovia", "rodoviari", "pavimenta", "estrada", "bueiro", "ponte", "viaduto"];
function classificar(objeto) {
  const texto = (objeto || "").toLowerCase();
  return PALAVRAS_RODOVIA.some(p => texto.includes(p)) ? "obra_rodoviaria" : "edital_aberto";
}

return registros.map(r => {
  const objeto = (r.objetoCompra || r.objeto || "Contratação pública").toString().slice(0, 500);
  return {
    json: {
      municipio_id: municipioId,
      source: "pncp",
      signal_type: classificar(objeto),
      title: objeto,
      value_numeric: r.valorTotalEstimado || r.valorGlobal || null,
      value_json: r,
      published_at: (r.dataPublicacaoPncp || r.dataInclusao || "").toString().slice(0, 10) || null,
      external_id: r.numeroControlePNCP || r.numeroControlePncp || `${r.sequencialCompra || ""}-${r.orgaoEntidade?.cnpj || ""}`,
    }
  };
});
